#!/usr/bin/env python3

import argparse
import concurrent.futures
import json
import threading
import time
import urllib.error
import urllib.request

NODE_LABEL = "ConcurrentEvent"
EDGE_LABEL = "CONCURRENT_EVENT_LINK"
ANCHOR_LABEL = "ConcurrentAnchor"
SEVERITY = "info"


def entry(name, root):
    return {"query": {"name": name, "root": root}}


def batch(kind, entries, returns=(), parameters=None, parameter_types=None):
    payload = {
        "request_type": kind,
        "query": {kind: {"entries": entries, "returns": list(returns)}},
    }
    if parameters is not None:
        payload["parameters"] = parameters
    if parameter_types is not None:
        payload["parameter_types"] = parameter_types
    return payload


def post(url, payload):
    request = urllib.request.Request(
        f"{url.rstrip('/')}/v2/query",
        data=json.dumps(payload).encode(),
        headers={"content-type": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(request, timeout=90) as response:
            return json.load(response)
    except urllib.error.HTTPError as error:
        body = error.read().decode(errors="replace")
        raise RuntimeError(f"query returned HTTP {error.code}: {body}") from error


def create_index(url, spec):
    response = post(
        url,
        batch(
            "write",
            [
                entry(
                    "operation",
                    {"create_index": {"spec": spec, "if_not_exists": True}},
                )
            ],
            ["operation"],
        ),
    )
    operation_id = response["operation"]["operation_id"]
    deadline = time.monotonic() + 30
    while True:
        status = post(
            url,
            batch(
                "read",
                [
                    entry(
                        "status",
                        {"get_index_operation": {"operation_id": operation_id}},
                    )
                ],
                ["status"],
            ),
        )["status"]["status"]
        if status == "succeeded":
            return
        if status not in ("queued", "running"):
            raise RuntimeError(f"index operation {operation_id} reached {status}")
        if time.monotonic() >= deadline:
            raise RuntimeError(f"index operation {operation_id} timed out")
        time.sleep(0.05)


def add_anchor(url):
    response = post(
        url,
        batch(
            "write",
            [
                entry(
                    "anchor",
                    {
                        "id": {
                            "input": {
                                "add_n": {"label": ANCHOR_LABEL, "properties": []}
                            }
                        }
                    },
                )
            ],
            ["anchor"],
        ),
    )
    return response["anchor"][0]


def insert_batch(url, anchor_id, offset, size):
    body = [
        entry(
            "created",
            {
                "add_n": {
                    "label": NODE_LABEL,
                    "properties": [
                        ["severity", {"value": {"string": SEVERITY}}],
                        ["key", {"expr": {"param": "key"}}],
                    ],
                }
            },
        ),
        entry(
            "linked",
            {
                "add_e": {
                    "input": {"nodes": {"reference": {"var": "created"}}},
                    "label": EDGE_LABEL,
                    "to": {"ids": [anchor_id]},
                    "properties": [["severity", {"value": {"string": SEVERITY}}]],
                }
            },
        ),
    ]
    data = [{"key": f"event-{index}"} for index in range(offset, offset + size)]
    return post(
        url,
        batch(
            "write",
            [{"for_each": {"param": "data", "body": body}}],
            parameters={"data": data},
            parameter_types={"data": {"array": "object"}},
        ),
    )


def delete_batch(url, ids):
    root = {"drop": {"input": {"nodes": {"reference": {"param": "ids"}}}}}
    return post(
        url,
        batch(
            "write",
            [entry("deleted", root)],
            parameters={"ids": ids},
            parameter_types={"ids": {"array": "i64"}},
        ),
    )


def equals(property_name, value):
    return {
        "eq": {
            "left": {"property": property_name},
            "right": {"constant": {"string": value}},
        }
    }


def label_predicate(label):
    return equals("$label", label)


def indexed_predicate(label):
    return {
        "and": {"predicates": [label_predicate(label), equals("severity", SEVERITY)]}
    }


def source(kind, predicate):
    return {kind: {"predicate": predicate}}


def count(input_root):
    return {"count": {"input": input_root}}


def read_state(url, anchor_id):
    names_and_roots = [
        (
            "node_ids",
            {"id": {"input": source("nodes_where", label_predicate(NODE_LABEL))}},
        ),
        (
            "node_index_count",
            count(source("nodes_where", indexed_predicate(NODE_LABEL))),
        ),
        (
            "edge_label_count",
            count(source("edges_where", label_predicate(EDGE_LABEL))),
        ),
        (
            "edge_index_count",
            count(source("edges_where", indexed_predicate(EDGE_LABEL))),
        ),
        (
            "adjacency_count",
            count(
                {
                    "in_e": {
                        "input": {"nodes": {"reference": {"ids": [anchor_id]}}},
                        "label": EDGE_LABEL,
                    }
                }
            ),
        ),
        (
            "anchor_count",
            count(source("nodes_where", label_predicate(ANCHOR_LABEL))),
        ),
    ]
    response = post(
        url,
        batch(
            "read",
            [entry(name, root) for name, root in names_and_roots],
            [name for name, _ in names_and_roots],
        ),
    )
    return tuple(response[name] for name, _ in names_and_roots)


def run_concurrently(tasks):
    started = time.monotonic()
    with concurrent.futures.ThreadPoolExecutor(max_workers=len(tasks)) as executor:
        barrier = threading.Barrier(len(tasks))

        def run(task):
            barrier.wait()
            return task()

        futures = [executor.submit(run, task) for task in tasks]
        for future in futures:
            future.result()
    return time.monotonic() - started


def chunks(values, count):
    size = len(values) // count
    return [values[index * size : (index + 1) * size] for index in range(count)]


def assert_state(url, anchor_id, expected):
    state = read_state(url, anchor_id)
    node_ids, node_index, edge_label, edge_index, adjacency, anchor_count = state
    if (
        len(node_ids) != expected
        or node_index != expected
        or edge_label != expected
        or edge_index != expected
        or adjacency != expected
        or anchor_count != 1
    ):
        raise RuntimeError(
            "unexpected graph/index state: "
            f"node_label={len(node_ids)} node_index={node_index} "
            f"edge_label={edge_label} edge_index={edge_index} "
            f"adjacency={adjacency} anchor={anchor_count}, "
            f"expected memberships={expected} anchor=1"
        )
    if len(set(node_ids)) != len(node_ids):
        raise RuntimeError("node label row returned duplicate IDs")
    return node_ids


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--url", required=True)
    parser.add_argument("--clients", type=int, default=8)
    parser.add_argument("--batch-size", type=int, default=128)
    args = parser.parse_args()
    if args.clients < 4 or args.clients % 2:
        parser.error("--clients must be an even number of at least four")
    if args.batch_size < 1:
        parser.error("--batch-size must be positive")

    create_index(
        args.url,
        {
            "node_equality": {
                "label": NODE_LABEL,
                "property": "severity",
                "unique": False,
            }
        },
    )
    create_index(
        args.url,
        {"edge_equality": {"label": EDGE_LABEL, "property": "severity"}},
    )
    anchor_id = add_anchor(args.url)

    expected = args.clients * args.batch_size
    insert_seconds = run_concurrently(
        [
            lambda index=index: insert_batch(
                args.url,
                anchor_id,
                index * args.batch_size,
                args.batch_size,
            )
            for index in range(args.clients)
        ]
    )
    node_ids = assert_state(args.url, anchor_id, expected)

    half = args.clients // 2
    mixed_tasks = [
        lambda ids=ids: delete_batch(args.url, ids)
        for ids in chunks(node_ids[: expected // 2], half)
    ] + [
        lambda index=index: insert_batch(
            args.url,
            anchor_id,
            expected + index * args.batch_size,
            args.batch_size,
        )
        for index in range(half)
    ]
    mixed_seconds = run_concurrently(mixed_tasks)
    node_ids = assert_state(args.url, anchor_id, expected)

    delete_seconds = run_concurrently(
        [
            lambda ids=ids: delete_batch(args.url, ids)
            for ids in chunks(node_ids, args.clients)
        ]
    )
    assert_state(args.url, anchor_id, 0)

    print(
        json.dumps(
            {
                "clients": args.clients,
                "batch_size": args.batch_size,
                "members_per_phase": expected,
                "insert_seconds": round(insert_seconds, 3),
                "mixed_seconds": round(mixed_seconds, 3),
                "delete_seconds": round(delete_seconds, 3),
                "failures": 0,
                "final_nodes": 0,
                "final_edges": 0,
                "anchor_nodes": 1,
            },
            sort_keys=True,
        )
    )


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Compare local disposable images against an independent write-time oracle.

Seed each empty server once, then compare fixture files. Timing includes the full
HTTP request and JSON transfer. First-request samples are not cold-cache claims.
"""
import argparse
import concurrent.futures
import json
import math
from pathlib import Path
import statistics
import time
import urllib.request


def request(port, payload):
    data = json.dumps(payload).encode()
    req = urllib.request.Request(f"http://127.0.0.1:{port}/v2/query", data=data,
                                 headers={"Content-Type": "application/json"})
    start = time.perf_counter()
    with urllib.request.urlopen(req, timeout=180) as response:
        body = response.read()
    elapsed = time.perf_counter() - start
    return json.loads(body), elapsed * 1000


def batch(kind, roots):
    names = [f"q{i}" for i in range(len(roots))]
    return {"request_type": kind, "query": {kind: {
        "entries": [{"query": {"name": name, "root": root}}
                    for name, root in zip(names, roots)], "returns": names}}}


def nodes(ids):
    return {"nodes": {"reference": {"ids": ids}}}


def properties(values):
    return [[key, {"value": {"string" if isinstance(value, str) else "i64": value}}]
            for key, value in values.items()]


def seed(args):
    roots, leaves, records = [], [], []
    for label, count, ids in [("DemandRoot", args.roots, roots),
                               ("DemandLeaf", args.degree, leaves)]:
        for start in range(0, count, 64):
            queries = [{"id": {"input": {"add_n": {"label": label, "properties":
                properties({"rank": rank, "kind": f"k{rank % 8}", "payload": "x" * args.payload})}}}}
                for rank in range(start, min(start + 64, count))]
            response, _ = request(args.port, batch("write", queries))
            for i in range(len(queries)):
                assert len(response[f"q{i}"]) == 1
                ids.append(response[f"q{i}"][0])

    pending = []

    def flush():
        response, _ = request(args.port, batch("write", [query for query, _ in pending]))
        for i, (_, expected) in enumerate(pending):
            actual = response[f"q{i}"]
            assert len(actual) == len(expected)
            # Use returned IDs only; verify every other field against the input.
            by_pair = {(item["$from"], item["$to"]): item for item in expected}
            for row in actual:
                values = {key: value for key, value in row.items() if key != "$id"}
                assert values == by_pair[(row["$from"], row["$to"])]
                records.append(row)
        pending.clear()

    def edge(from_ids, to_ids, values, label="DemandLink"):
        query = {"edge_properties": {"input": {"add_e": {
            "input": nodes(from_ids), "to": {"ids": to_ids}, "label": label,
            "properties": properties(values)}}}}
        expected = [{"$from": source, "$to": target, "$label": label, **values}
                    for source in from_ids for target in to_ids]
        pending.append((query, expected))
        if len(pending) == 32:
            flush()

    for start in range(0, len(roots), 64):
        group = roots[start:start + 64]
        for i, leaf in enumerate(leaves):
            values = {"kind": f"k{i % 8}", "ordinal": i, "payload": "x" * args.payload}
            if i % 2:
                edge([leaf], group, values)
            else:
                edge(group, [leaf], values)
            # Parallel edges must remain separate occurrences.
            if i % 2:
                edge([leaf], group, values, "AlternateLink")
            else:
                edge(group, [leaf], values, "AlternateLink")
        print(json.dumps({"seeded_roots": min(start + 64, len(roots)), "port": args.port}), flush=True)
    for root in roots:
        edge([root], [root], {})
    if len(roots) > 1:
        edge([roots[0]], [roots[1]], {"kind": "k0", "payload": "shared"})
    if pending:
        flush()
    fixture = {"port": args.port, "roots": roots, "leaves": leaves,
               "records": records, "payload": args.payload, "degree": args.degree}
    args.fixture.write_text(json.dumps(fixture))
    print(json.dumps({"fixture": str(args.fixture), "edges": len(records)}), flush=True)


def case(fixture, take, selectivity, root_count, projection="id", sort=False):
    roots = fixture["roots"][:root_count]
    accepted = {
        "dense": lambda row: row.get("kind") in {f"k{i}" for i in range(8)},
        "sparse": lambda row: row.get("kind") == "k0",
        "late": lambda row: row.get("ordinal") == fixture["degree"] - 1,
        "none": lambda row: row.get("ordinal") == fixture["degree"],
    }[selectivity]
    if selectivity == "dense":
        predicate = {"is_in": {"value": {"property": "kind"},
                               "values": {"constant": {"string_array": [f"k{i}" for i in range(8)]}}}}
    else:
        key, value = ("kind", {"string": "k0"}) if selectivity == "sparse" else (
            "ordinal", {"i64": fixture["degree"] - (selectivity == "late")})
        predicate = {"eq": {"left": {"property": key}, "right": {"constant": value}}}
    traversal = {"where": {"input": {"both_e": {"input": nodes(roots)}}, "predicate": predicate}}
    adjacent = {root: [] for root in roots}
    for row in fixture["records"]:
        if accepted(row):
            for root in {row["$from"], row["$to"]} & adjacent.keys():
                adjacent[root].append(row)
    rows = [row for root in roots for row in sorted(adjacent[root], key=lambda r: r["$id"])]
    if sort:
        traversal = {"order_by": {"input": traversal, "property": "$id", "order": "desc"}}
        rows.sort(key=lambda row: row["$id"], reverse=True)
    if take is not None:
        traversal = {"limit": {"input": traversal, "count": {"literal": take}}}
        rows = rows[:take]
    payload = batch("read", [{projection: {"input": traversal}}])
    expected = {"q0": ([row["$id"] for row in rows] if projection == "id" else rows) or (None if take in (0, 1) else [])}
    return payload, expected


def verify(args):
    fixture = json.loads(args.fixture.read_text())
    roots = fixture["roots"]
    identity = {"root": "context"}
    empty = {"root": {"limit": {"input": "context", "count": {"literal": 0}}}}
    for operation, config in [
        ("union", {"traversals": [identity, identity]}),
        ("coalesce", {"traversals": [empty, identity]}),
        ("optional", {"traversal": empty}),
        ("repeat", {"config": {"traversal": identity, "times": 3, "emit": "before", "max_depth": 3}}),
    ]:
        child = {operation: {"input": nodes(roots), **config}}
        query = {"id": {"input": {"limit": {"input": child, "count": {"literal": 1}}}}}
        actual, _ = request(fixture["port"], batch("read", [query]))
        assert actual == {"q0": [roots[0]]}, (operation, actual)
    for take in (0, 1, len(roots)):
        for before in (True, False):
            def update(input_node, value):
                return {"set_property": {"input": input_node, "name": "demand_marker", "value": {"value": {"i64": value}}}}
            request(fixture["port"], batch("write", [update(nodes(roots), 0)]))
            limited = lambda node: {"limit": {"input": node, "count": {"literal": take}}}
            changed = update(limited(nodes(roots)), 1) if before else limited(update(nodes(roots), 1))
            request(fixture["port"], batch("write", [changed]))
            read = {"id": {"input": {"where": {"input": nodes(roots), "predicate": {
                "eq": {"left": {"property": "demand_marker"}, "right": {"constant": {"i64": 1}}}}}}}}
            actual, _ = request(fixture["port"], batch("read", [read]))
            expected = roots[:take] if before else roots
            assert actual == {"q0": expected}, ("mutation", take, before, actual)
    print(json.dumps({"port": fixture["port"], "nested_and_mutation_contracts": "passed"}), flush=True)


def cold(args):
    import subprocess
    fixtures = [json.loads(path.read_text()) for path in (args.baseline, args.candidate)]
    containers = [args.baseline_container, args.candidate_container]
    for selectivity in ("dense", "late", "none"):
        for take in (0, 1, 10, 100, None):
            runs = [case(f, take, selectivity, len(f["roots"])) for f in fixtures]
            timings = [[], []]
            for iteration in range(args.samples):
                for index in ([0, 1] if iteration % 2 == 0 else [1, 0]):
                    subprocess.run(["docker", "restart", containers[index]], check=True, stdout=subprocess.DEVNULL)
                    deadline = time.monotonic() + 60
                    while True:
                        try:
                            with urllib.request.urlopen(f"http://127.0.0.1:{fixtures[index]['port']}/healthz", timeout=2) as response:
                                if response.status == 200:
                                    break
                        except (OSError, urllib.error.URLError):
                            if time.monotonic() >= deadline:
                                raise
                        time.sleep(0.05)
                    actual, elapsed = request(fixtures[index]["port"], runs[index][0])
                    assert actual == runs[index][1], (selectivity, take, index)
                    timings[index].append(elapsed)
            medians = [statistics.median(values) for values in timings]
            print(json.dumps({"selectivity": selectivity, "take": take,
                "cache_state": "server restarted; host filesystem cache retained",
                "baseline_p50_ms": medians[0], "candidate_p50_ms": medians[1],
                "samples_ms": timings, "speedup": medians[0] / medians[1],
                "ordered_results_verified": True}), flush=True)


def compare(args):
    import hashlib
    fixtures = [json.loads(path.read_text()) for path in (args.baseline, args.candidate)]
    assert fixtures[0]["port"] != fixtures[1]["port"]
    assert [(len(f["roots"]), f["degree"], f["payload"]) for f in fixtures][0] == (
        len(fixtures[1]["roots"]), fixtures[1]["degree"], fixtures[1]["payload"])
    for roots in sorted({1, len(fixtures[0]["roots"])}):
        for selectivity in ("dense", "sparse", "late", "none"):
            for take in (0, 1, 10, 100, None):
                runs = [case(f, take, selectivity, roots, args.projection, args.sort) for f in fixtures]
                timings = [[], []]
                first = [[], []]
                for iteration in range(args.samples + 2):
                    for index in ([0, 1] if iteration % 2 == 0 else [1, 0]):
                        payload, expected = runs[index]
                        with concurrent.futures.ThreadPoolExecutor(max_workers=args.workers) as pool:
                            responses = list(pool.map(lambda _: request(fixtures[index]["port"], payload), range(args.workers)))
                        for actual, elapsed in responses:
                            assert actual == expected, (selectivity, take, roots, index, "ordered result mismatch", actual, expected)
                            if iteration >= 2:
                                timings[index].append(elapsed)
                            elif iteration == 0:
                                first[index].append(elapsed)
                medians = [statistics.median(values) for values in timings]
                print(json.dumps({"selectivity": selectivity, "take": take, "roots": roots,
                    "degree": fixtures[0]["degree"], "payload_bytes": fixtures[0]["payload"],
                    "projection": args.projection, "workers": args.workers, "full_input_sort": args.sort,
                    "baseline_p50_ms": medians[0], "candidate_p50_ms": medians[1],
                    "speedup": medians[0] / medians[1], "samples_ms": timings,
                    "p95_ms": [sorted(values)[math.ceil(0.95 * len(values)) - 1] for values in timings],
                    "first_request_ms": first, "ordered_results_verified": True,
                    "result_sha256": [hashlib.sha256(json.dumps(r[1], sort_keys=True).encode()).hexdigest() for r in runs]}), flush=True)


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    commands = parser.add_subparsers(dest="command", required=True)
    seed_parser = commands.add_parser("seed")
    seed_parser.add_argument("--port", type=int, required=True)
    seed_parser.add_argument("--fixture", type=Path, required=True)
    seed_parser.add_argument("--roots", type=int, default=128)
    seed_parser.add_argument("--degree", type=int, default=128)
    seed_parser.add_argument("--payload", type=int, default=64)
    verification = commands.add_parser("verify")
    verification.add_argument("--fixture", type=Path, required=True)
    cold_parser = commands.add_parser("cold")
    cold_parser.add_argument("--baseline", type=Path, required=True)
    cold_parser.add_argument("--candidate", type=Path, required=True)
    cold_parser.add_argument("--baseline-container", required=True)
    cold_parser.add_argument("--candidate-container", required=True)
    cold_parser.add_argument("--samples", type=int, default=7)
    comparison = commands.add_parser("compare")
    comparison.add_argument("--baseline", type=Path, required=True)
    comparison.add_argument("--candidate", type=Path, required=True)
    comparison.add_argument("--sort", action="store_true", help="sort the complete filtered input before limiting")
    comparison.add_argument("--samples", type=int, default=7)
    comparison.add_argument("--workers", type=int, default=1)
    comparison.add_argument("--projection", choices=("id", "edge_properties"), default="id")
    args = parser.parse_args()
    if args.command == "seed":
        if args.roots < 1 or args.degree < 1 or args.payload < 0 or args.fixture.exists():
            parser.error("positive roots/degree, nonnegative payload and a new fixture path required")
        seed(args)
    elif args.command == "verify":
        verify(args)
    elif args.command == "cold":
        if args.samples < 7:
            parser.error("at least seven cold samples required")
        cold(args)
    else:
        if args.samples < 7 or args.workers < 1:
            parser.error("at least seven samples and positive workers required")
        compare(args)

#!/usr/bin/env python3
"""Check early-termination value contracts against a seeded smoke-test server."""
import json
import sys
import urllib.error
import urllib.request


def query(port, root, saved=None):
    payload = {"request_type": "read", "query": {"read": {
        "entries": [{"query": {"name": "result", "root": root}}],
        "returns": ["result"],
    }}}
    if saved is not None:
        payload["query"]["read"]["entries"].insert(0, {
            "query": {"name": "saved", "root": saved},
        })
    req = urllib.request.Request(
        f"http://127.0.0.1:{port}/v2/query",
        data=json.dumps(payload).encode(),
        headers={"Content-Type": "application/json"},
    )
    with urllib.request.urlopen(req, timeout=30) as response:
        return json.load(response)["result"]


def check(port):
    source = {"has_label": {"input": {"nodes": {"reference": "all"}},
                            "label": "DockerImageSmokeUser"}}
    count = query(port, {"count": {"input": source}})
    ids = query(port, {"id": {"input": source}})
    assert ids, "smoke fixture must contain nodes"
    for matches in (True, False):
        condition = {"eq": {"left": {"property": "scenario"},
                            "right": {"constant": {"string":
                                "docker-image-smoke" if matches else "absent"}}}}
        for projection, expected in (("count", [count]), ("id", ids[:1])):
            child = {"root": {projection: {"input": "context"}}}
            for has_else in (False, True):
                branch = {"input": source, "condition": condition, "then_traversal": child}
                if has_else:
                    branch["else_traversal"] = child
                root = {"limit": {"input": {"choose": branch}, "count": {"literal": 1}}}
                actual = query(port, root)
                assert actual == (expected if matches or has_else else None), (root, actual)

    # Full-input operators must reject scalar input even under zero demand.
    empty = {"has_label": {"input": {"nodes": {"reference": "all"}},
                           "label": "MissingEarlyTerminationFixture"}}
    for input_rows in (empty, source):
        for operator in ("label", "fold", "unfold"):
            for take in (0, 1):
                root = {"limit": {"input": {operator: {"input": {"id": {"input": input_rows}}}},
                                  "count": {"literal": take}}}
                try:
                    query(port, root)
                except urllib.error.HTTPError as error:
                    body = json.loads(error.read())
                    assert body.get("error") == "invalid_query", body
                else:
                    raise AssertionError(f"{operator} accepted a scalar input with limit {take}")

    # Saved operands must be validated before any window can stop polling.
    for operator in ("inject", "within", "without"):
        for input_rows in (empty, source):
            for saved_rows in (empty, source):
                for take in (None, 0, 1, count + 1):
                    window = {operator: {"input": input_rows, "variable": "saved"}}
                    if take is not None:
                        window = {"limit": {"input": window, "count": {"literal": take}}}
                    for terminal in ("id", "count", "exists"):
                        root = {terminal: {"input": window}}
                        try:
                            query(port, root, saved={"id": {"input": saved_rows}})
                        except urllib.error.HTTPError as error:
                            body = json.loads(error.read())
                            assert body.get("error") == "invalid_query", body
                        else:
                            raise AssertionError(
                                f"{operator} accepted scalar saved operand with limit {take} and {terminal}"
                            )
                        # Valid row operands preserve ordering and duplicate semantics.
                        left = ids if input_rows == source else []
                        right = ids if saved_rows == source else []
                        if operator == "inject":
                            expected = left + right
                        elif operator == "within":
                            expected = [item for item in left if item in right]
                        else:
                            expected = [item for item in left if item not in right]
                        expected = expected[:take]
                        if terminal == "count":
                            expected = len(expected)
                        elif terminal == "exists":
                            expected = bool(expected)
                        actual = query(port, root, saved=saved_rows)
                        # Existing empty scalar projections can serialize as
                        # null for a known-empty plan or [] for a drained plan.
                        if terminal == "id" and actual is None:
                            actual = []
                        assert actual == expected, (root, actual, expected)
                        folded = {"fold": {"input": saved_rows}}
                        if operator == "inject":
                            try:
                                query(port, root, saved=folded)
                            except urllib.error.HTTPError as error:
                                body = json.loads(error.read())
                                assert body.get("error") == "invalid_query", body
                            else:
                                raise AssertionError(f"inject accepted folded operand with limit {take}")
                        else:
                            try:
                                actual = query(port, root, saved=folded)
                            except urllib.error.HTTPError as error:
                                raise AssertionError(
                                    f"{operator} rejected folded operand with limit {take} and {terminal}"
                                ) from error
                            if terminal == "id" and actual is None:
                                actual = []
                            assert actual == expected, (root, actual, expected)

    # Enter the repeat body with a large frontier before satisfying LIMIT 1.
    large = {"nodes": {"reference": {"ids": ids[:1]}}}
    for _ in range(12):
        large = {"union": {"input": large, "traversals": [
            {"root": "context"}, {"root": "context"},
        ]}}
    assert query(port, {"count": {"input": large}}) == 4096
    repeat = {"repeat": {"input": large, "config": {
        "traversal": {"root": "context"}, "times": 1, "emit": "after", "max_depth": 1,
    }}}
    assert query(port, {"id": {"input": {"limit": {"input": repeat,
                    "count": {"literal": 1}}}}}) == ids[:1]
    print("early-termination conditional values and saved-operand type contracts passed")


if __name__ == "__main__":
    check(int(sys.argv[1]))

#!/usr/bin/env python3
"""Synthetic equality benchmark on disposable localhost images.

Checks every complete response against the fixture oracle. Empty and rare
matches use the same three indexed predicates and ordinary bound parameters.
Run with --no-seed --ordered to check both ordered projections on the same
fixture. Timings are measurements; planner estimates are not work
counters and are deliberately not reported as measured I/O.
"""

import argparse
import concurrent.futures
import json
import statistics
import threading
import time
from pathlib import Path

import range_benchmark as bench


def lookup(resource_type="pod"):
    predicate = {"and": {"predicates": [
        {"eq": {"left": {"property": prop}, "right": {"param": prop}}}
        for prop in ["tenant", "type", "deleted"]
    ]}}
    predicate["and"]["predicates"].insert(0, {"eq": {
        "left": {"property": "$label"}, "right": {"constant": {"string": "Resource"}}
    }})
    request = bench.batch("read", [{"values": {
        "input": {"nodes_where": {"predicate": predicate}}, "properties": ["id"],
    }}])
    request["parameters"] = {"tenant": bench.TENANT, "type": resource_type, "deleted": True}
    request["query_name"] = "equality_intersection"
    return request


def fixture_rows(size, raw_bytes):
    rows = bench.fixture_rows(size, raw_bytes, False)
    for index, row in enumerate(rows):
        row["deleted"] = index % 997 == 0
    return rows


def type_union_lookup(resource_types):
    request = bench.batch("read", [{"values": {
        "input": {"nodes_where": {"predicate": {"and": {"predicates": [
            {"eq": {"left": {"property": "$label"}, "right": {"constant": {"string": "Resource"}}}},
            {"or": {"predicates": [{"eq": {"left": {"property": "type"}, "right": {"param": f"type-{index}"}}}
                                    for index in range(len(resource_types))]}},
            {"eq": {"left": {"property": "tenant"}, "right": {"param": "tenant"}}},
        ]}}}}, "properties": ["id"],
    }}])
    request["parameters"] = {"tenant": bench.TENANT, **{f"type-{index}": value for index, value in enumerate(resource_types)}}
    request["query_name"] = "equality_type_union"
    return request


def prepare(port, rows):
    for prop in ["tenant", "type", "deleted", "last_seen"]:
        family = "node_range" if prop == "last_seen" else "node_equality"
        spec = {"label": "Resource", "property": prop}
        spec.update({"direction": "asc"} if family == "node_range" else {"unique": False})
        receipt, _ = bench.request(port, bench.batch("write", [{"create_index": {
            "spec": {family: spec}, "if_not_exists": True,
        }}]))
        operation = receipt["q0"].get("operation_id")
        if operation:
            deadline = time.monotonic() + 120
            while True:
                status, _ = bench.request(port, bench.batch("read", [{"get_index_operation": {"operation_id": operation}}]))
                state = status["q0"]["status"]
                if state == "succeeded":
                    break
                if state in ["failed", "blocked", "aborted"] or time.monotonic() >= deadline:
                    raise RuntimeError(status)
                time.sleep(.05)
    for offset in range(0, len(rows), 100):
        roots = [{"add_n": {"label": "Resource", "properties": [
            [key, {"value": {"bool" if isinstance(value, bool) else "i64" if isinstance(value, int) else "string": value}}]
            for key, value in row.items()
        ]}} for row in rows[offset:offset + 100]]
        bench.request(port, bench.batch("write", roots))


def expected_ids(rows, resource_type):
    return sorted(row["id"] for row in rows if row["tenant"] == bench.TENANT
                  and row["type"] == resource_type and row["deleted"])


def check_result(result, expected):
    actual = result["q0"]
    assert sorted(actual, key=lambda row: row["id"]) == [{"id": value} for value in expected], (actual, expected)


def run(args):
    rows = fixture_rows(args.size, args.raw_bytes)
    ports = [args.baseline, args.candidate]
    if not args.no_seed:
        for port in ports:
            prepare(port, rows)
    report = {"rows": len(rows), "raw_bytes": args.raw_bytes, "samples": args.samples,
              "mode": "warm", "workers": args.workers, "churn": args.churn, "cases": []}
    cases = [("rare" if resource_type == "pod" else "empty", lookup(resource_type), expected_ids(rows, resource_type))
             for resource_type in ["pod", "no-matching-type"]]
    cases.append(("equality_type_union", type_union_lookup(["pod", "no-matching-type"]),
                  sorted(row["id"] for row in rows if row["tenant"] == bench.TENANT and row["type"] == "pod")))
    if args.ordered:
        cases = []
        for fixture in ["ordered-range-wide-projection.json", "ordered-range-narrow-projection.json"]:
            for window in ["broad", "narrow"]:
                payload = json.loads((bench.FIXTURES / fixture).read_text())
                cutoff = bench.CUTOFF if window == "broad" else bench.CUTOFF + len(rows) - 100
                payload["parameters"]["since_last_seen_us"] = cutoff
                projection = payload["query"]["read"]["entries"][0]["query"]["root"]["value_map"]["properties"]
                selected = sorted((row for row in rows if row["tenant"] == bench.TENANT and row["type"] == "pod" and row["last_seen"] > cutoff), key=lambda row: -row["last_seen"])
                expected = [{key: row[key] for key in projection if key in row} for row in selected[:1000]]
                cases.append((fixture + ":" + window, payload, expected))
    for case_name, payload, expected in cases:
        measurements = {port: [] for port in ports}
        for sample in range(args.samples + 3):
            for port in ports if sample % 2 == 0 else ports[::-1]:
                with concurrent.futures.ThreadPoolExecutor(max_workers=args.workers) as pool:
                    responses = list(pool.map(lambda _: bench.request(port, payload), range(args.workers)))
                for result, elapsed in responses:
                    if args.ordered:
                        assert bench.normalized(result) == expected, (case_name, port)
                    else:
                        check_result(result, expected)
                    if sample >= 3:
                        measurements[port].append(elapsed)
        timing = {role: {"p50_ms": statistics.median(measurements[port]) * 1000,
                         "p95_ms": bench.percentile(measurements[port], .95) * 1000,
                         "max_ms": max(measurements[port]) * 1000,
                         "n": len(measurements[port])}
                  for role, port in [("baseline", args.baseline), ("candidate", args.candidate)]}
        case = {"case": case_name, "results": len(expected), **timing}
        report["cases"].append(case)
        print(json.dumps(case), flush=True)
    if args.output:
        Path(args.output).write_text(json.dumps(report, indent=2) + "\n")
    return report


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--baseline", type=int, default=18250)
    parser.add_argument("--candidate", type=int, default=18251)
    parser.add_argument("--size", type=int, default=2000)
    parser.add_argument("--raw-bytes", type=int, default=4096)
    parser.add_argument("--samples", type=int, default=30)
    parser.add_argument("--workers", type=int, default=1)
    parser.add_argument("--no-seed", action="store_true")
    parser.add_argument("--churn", action="store_true")
    parser.add_argument("--ordered", action="store_true")
    parser.add_argument("--output")
    args = parser.parse_args()
    if args.size < 1 or args.samples < 1 or args.workers < 1:
        parser.error("size, samples and workers must be positive")
    if args.churn:
        if not args.no_seed:
            parser.error("seed before starting concurrent churn")
        stop = threading.Event()
        with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
            writers = [pool.submit(bench.churn, port, stop) for port in [args.baseline, args.candidate]]
            try:
                run(args)
            finally:
                stop.set()
                for writer in writers:
                    print(json.dumps(writer.result()), flush=True)
    else:
        run(args)

#!/usr/bin/env python3
"""Paired HTTP benchmark on two disposable, empty local HelixDB images.

Uses the checked-in customer requests and a fixed fixture clock. No production
credentials or endpoint defaults are accepted. Each request is checked against
an independently sorted fixture. This measures warm reads; cold storage and
churn runs must be reported separately.
"""
import argparse
import concurrent.futures
import threading
import json
import http.client
import math
import statistics
import time
import urllib.error
import urllib.request
from pathlib import Path

FIXTURES = Path(__file__).parent / 'fixtures'
CUTOFF = 1788000000000000
TENANT = 'FZob8v6ZTnCcuVk4'


def request(port, payload):
    wire = json.dumps(payload).encode()
    started = time.perf_counter()
    req = urllib.request.Request(f'http://127.0.0.1:{port}/v2/query', wire,
                                 {'content-type': 'application/json'})
    try:
        with urllib.request.urlopen(req, timeout=180) as response:
            result = json.load(response)
    except urllib.error.HTTPError as error:
        raise RuntimeError(error.read().decode()) from error
    return result, time.perf_counter() - started


def batch(kind, roots):
    return {'request_type': kind, 'query': {kind: {
        'entries': [{'query': {'name': f'q{i}', 'root': root}}
                    for i, root in enumerate(roots)],
        'returns': [f'q{i}' for i in range(len(roots))]}}}


def prepare(port, rows):
    deadline = time.monotonic() + 60
    while True:
        try:
            with urllib.request.urlopen(f'http://127.0.0.1:{port}/readyz', timeout=1):
                break
        except (urllib.error.URLError, TimeoutError, http.client.RemoteDisconnected, ConnectionResetError):
            if time.monotonic() >= deadline:
                raise TimeoutError(f'local server {port} did not become ready')
            time.sleep(.05)
    for prop in ['tenant', 'type', 'last_seen']:
        spec = {'label': 'Resource', 'property': prop}
        family = 'node_range' if prop == 'last_seen' else 'node_equality'
        spec.update({'direction': 'asc'} if prop == 'last_seen' else {'unique': False})
        receipt, _ = request(port, batch('write', [{'create_index': {
            'spec': {family: spec}, 'if_not_exists': True}}]))
        operation = receipt['q0'].get('operation_id')
        if operation:
            deadline = time.monotonic() + 120
            while True:
                status, _ = request(port, batch('read', [{'get_index_operation': {'operation_id': operation}}]))
                state = status['q0']['status']
                if state == 'succeeded':
                    break
                if state in ['failed', 'blocked', 'aborted'] or time.monotonic() > deadline:
                    raise RuntimeError(status)
                time.sleep(.1)
    for start in range(0, len(rows), 100):
        roots = [{'add_n': {'label': 'Resource', 'properties': [
            [key, {'value': {'i64' if isinstance(value, int) else 'string': value}}]
            for key, value in row.items()]}} for row in rows[start:start + 100]]
        request(port, batch('write', roots))
    print(json.dumps({'seeded_port': port, 'rows': len(rows)}), flush=True)


def fixture_rows(size, raw_bytes, tied, full_properties=False):
    projection = json.loads((FIXTURES / 'ordered-range-wide-projection.json').read_text())['query']['read']['entries'][0]['query']['root']['value_map']['properties']
    rows = []
    for i in range(size * 5):
        # Exactly 20% belong to the target; matching IDs are interleaved.
        row = {'id': f'resource-{i:08}', 'tenant': TENANT if i % 5 == 0 else f'other-{i % 4}',
               'type': 'pod' if i % 5 in (0, 1) else 'service',
               'last_seen': CUTOFF + (1 if tied else i + 1),
               'cluster_id': 'fixture-cluster', 'namespace': 'fixture',
               'name': f'name-{i:08}', 'raw_data': 'x' * raw_bytes}
        if full_properties:
            row = {**{key: f'fixture-{key}' for key in projection}, **row}
        rows.append(row)
    return rows


def normalized(result):
    return [row.get('properties', row) for row in result['q']]


def percentile(values, percentile):
    return sorted(values)[max(0, math.ceil(len(values) * percentile) - 1)]


def calibrate(port, size, samples):
    payload = json.loads((FIXTURES / 'ordered-range-narrow-projection.json').read_text())
    payload['parameters']['limit'] = size
    order = payload['query']['read']['entries'][0]['query']['root']['value_map']['input']['limit']['input']['order_by']
    timings = {'asc': [], 'desc': []}
    for sample in range(samples + 3):
        directions = ['asc', 'desc'] if sample % 2 == 0 else ['desc', 'asc']
        results = {}
        for direction in directions:
            order['order'] = direction
            result, elapsed = request(port, payload)
            results[direction] = normalized(result)
            assert len(results[direction]) == size
            if sample >= 3:
                timings[direction].append(elapsed)
        # Fixture IDs sort in insertion/entity-ID order. Build both orderings
        # independently so a shared tie-order bug cannot pass calibration.
        ascending = sorted(results['asc'], key=lambda row: (row['last_seen'], row['id']))
        descending = sorted(ascending, key=lambda row: -row['last_seen'])
        assert results['asc'] == ascending
        assert results['desc'] == descending
    forward = statistics.median(timings['asc'])
    reverse = statistics.median(timings['desc'])
    result = {'forward_p50_s': forward, 'reverse_p50_s': reverse,
              'extra_us_per_visited_entry': (reverse - forward) * 1e6 / (size * 5),
              'entries_per_scan': size * 5, 'samples': samples}
    print(json.dumps(result), flush=True)
    return result


def run(args):
    rows = fixture_rows(args.size, args.raw_bytes, args.tied, args.full_properties)
    if not args.no_seed:
        # Seed independently, with the same insertion order and properties.
        for port in [args.baseline, args.candidate]:
            prepare(port, rows)
    report = {'size': args.size, 'raw_bytes': args.raw_bytes, 'tied': args.tied,
              'samples': args.samples, 'full_properties': args.full_properties, 'mode': 'warm', 'workers': args.workers, 'churn': args.churn, 'cases': []}
    for path in [FIXTURES / 'ordered-range-wide-projection.json',
                 FIXTURES / 'ordered-range-narrow-projection.json']:
        for window in (['broad', 'narrow'] if args.window == 'both' else [args.window]):
            payload = json.loads(path.read_text())
            cutoff = CUTOFF if window == 'broad' else CUTOFF + len(rows) - min(100, len(rows))
            payload['parameters']['since_last_seen_us'] = cutoff
            projection = payload['query']['read']['entries'][0]['query']['root']['value_map']['properties']
            selected = [row for row in rows if row['tenant'] == TENANT and row['type'] == 'pod' and row['last_seen'] > cutoff]
            # Insertion order supplies the existing ascending internal ID tie order.
            selected.sort(key=lambda row: -row['last_seen'])
            expected = [{key: row[key] for key in projection if key in row} for row in selected[:1000]]
            measurements = {args.baseline: [], args.candidate: []}
            for sample in range(args.samples + 3):
                ports = [args.baseline, args.candidate] if sample % 2 == 0 else [args.candidate, args.baseline]
                for port in ports:
                    if args.workers == 1:
                        responses = [request(port, payload)]
                    else:
                        with concurrent.futures.ThreadPoolExecutor(max_workers=args.workers) as pool:
                            responses = list(pool.map(lambda _: request(port, payload), range(args.workers)))
                    for result, elapsed in responses:
                        actual = normalized(result)
                        assert actual == expected, (port, path.name, window, actual[:1], expected[:1], len(actual), len(expected))
                        if sample >= 3:
                            measurements[port].append(elapsed)
            timing = {label: {'p50_s': statistics.median(measurements[port]),
                              'p95_s': percentile(measurements[port], .95)}
                      for label, port in [('baseline', args.baseline), ('candidate', args.candidate)]}
            ratios = {metric: timing['candidate'][metric] / timing['baseline'][metric] for metric in ['p50_s', 'p95_s']}
            gate = .5 if window == 'broad' else 1.1
            case = {'query': payload['query_name'], 'window': window, **timing,
                    'candidate_baseline_ratio': ratios, 'gate_passed': all(ratio <= gate for ratio in ratios.values())}
            report['cases'].append(case)
            print(json.dumps(case), flush=True)
    if args.output:
        Path(args.output).write_text(json.dumps(report, indent=2) + '\n')
    if args.require_gates and not all(case['gate_passed'] for case in report['cases']):
        raise SystemExit('Performance gate failed; inspect the saved measurements')
    return report


def churn(port, stop):
    cycles = 0
    while not stop.is_set():
        root = {'add_n': {'label': 'Resource', 'properties': [
            ['tenant', {'value': {'string': 'churn'}}],
            ['type', {'value': {'string': 'event'}}],
            ['last_seen', {'value': {'i64': CUTOFF + 999999}}],
            ['raw_data', {'value': {'string': 'x' * 4096}}]]}}
        result, _ = request(port, batch('write', [root] * 20))
        ids = [node['$id'] for value in result.values() for node in value]
        source = {'nodes': {'reference': {'ids': ids}}}
        request(port, batch('write', [{'set_property': {'input': source, 'name': 'last_seen', 'value': {'value': {'i64': CUTOFF + 999998}}}}]))
        request(port, batch('write', [{'drop': {'input': source}}]))
        cycles += 1
        stop.wait(.05)
    return {'port': port, 'insert_update_delete_cycles': cycles, 'entities_per_cycle': 20}



if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--baseline', type=int, default=18190)
    parser.add_argument('--candidate', type=int, default=18191)
    parser.add_argument('--size', type=int, default=10000)
    parser.add_argument('--raw-bytes', type=int, default=1024)
    parser.add_argument('--samples', type=int, default=30)
    parser.add_argument('--tied', action='store_true')
    parser.add_argument('--no-seed', action='store_true')
    parser.add_argument('--output')
    parser.add_argument('--calibrate', action='store_true')
    parser.add_argument('--workers', type=int, default=1)
    parser.add_argument('--churn', action='store_true')
    parser.add_argument('--require-gates', action='store_true')
    parser.add_argument('--full-properties', action='store_true')
    parser.add_argument('--window', choices=['broad', 'narrow', 'both'], default='both')
    args = parser.parse_args()
    if args.calibrate:
        result = calibrate(args.candidate, args.size, args.samples)
        if args.output:
            Path(args.output).write_text(json.dumps(result, indent=2) + '\n')
    elif args.churn:
        assert args.no_seed, 'seed the paired fixtures before concurrent churn'
        stop = threading.Event()
        with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:
            writers = [pool.submit(churn, port, stop) for port in [args.baseline, args.candidate]]
            try:
                run(args)
            finally:
                stop.set()
                for writer in writers:
                    print(json.dumps(writer.result()), flush=True)
    else:
        run(args)

//! Compile-tested mirror of the Usage example in
//! [`helix-dsl-macros/README.md`](../helix-dsl-macros/README.md).
//!
//! `#[query]` helpers return `Result<QueryRequest, QueryError>`.

#![recursion_limit = "256"]

use helix_db::dsl::prelude::*;

#[query]
fn find_user(username: String) -> ReadBatch {
    read_batch()
        .var_as(
            "user",
            g().n_where(SourcePredicate::eq("username", username)),
        )
        .returning(["user"])
}

#[query]
fn create_post(title: String) -> WriteBatch {
    write_batch()
        .var_as("post", g().add_n("Post", vec![("title", title)]))
        .returning(["post"])
}

fn main() -> Result<(), QueryError> {
    let request = find_user("alice".to_string())?;
    assert_eq!(request.query_name(), Some("find_user"));

    let request = create_post("hello".to_string())?;
    assert_eq!(request.query_name(), Some("create_post"));
    Ok(())
}

//! Compile-tested mirror of the `### Query functions` example in
//! [`sdks/rust/README.md`](../README.md).
//!
//! `#[query]` helpers return `Result<QueryRequest, QueryError>`.

#![recursion_limit = "256"]

use helix_db::dsl::prelude::*;
use helix_db::Client;
use serde::Deserialize;

#[query]
pub fn add_user(name: String) -> WriteBatch {
    write_batch()
        .var_as("user_id", g().add_n("user", vec![("name", name)]))
        .returning(vec!["user_id"])
}

#[derive(Deserialize)]
struct AddUserResponse {
    user_id: u64,
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let client = Client::new(Some("https://11e2fc88c410fa5eb13e.cluster.helix-db.com"))?
        .with_api_key(Some("hx_your_api_key"));

    // Handle QueryError from parameter coercion / request construction.
    let request = add_user("John".to_string())?;

    let response: AddUserResponse = client.query(request).send().await?;
    println!("created user {}", response.user_id);
    Ok(())
}

