//! Exercise the production executable, including its real process entry point.

use std::{process::Stdio, time::Duration};
use tokio::{
    io::{AsyncReadExt, AsyncWriteExt},
    process::Command,
};

fn command() -> Command {
    let mut command = Command::new(env!("CARGO_BIN_EXE_helix-opencypher-tck"));
    command
        .env("HELIX_TELEMETRY_LEVEL", "off")
        .env("HELIX_NO_UPDATE_CHECK", "1")
        .kill_on_drop(true);
    command
}

#[tokio::test]
async fn one_worker_uses_fresh_databases_and_reports_production_progress_and_errors() {
    let mut child = command()
        .arg("--worker")
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()
        .unwrap();
    let mut input = child.stdin.take().unwrap();
    let mut output = child.stdout.take().unwrap();
    tokio::time::timeout(Duration::from_secs(30), async {
        for (id, setup, query, assertion, planned, passes) in [
            ("created", "Given having executed:\n      \"\"\"\n      CREATE (:N)\n      \"\"\"\n    ", "MATCH (n) RETURN count(n) AS count", "the result should be, in any order:\n      | count |\n      | 1 |", true, true),
            ("fresh", "", "MATCH (n) RETURN count(n) AS count", "the result should be, in any order:\n      | count |\n      | 0 |", true, true),
            ("compile", "", "RETURN missing", "a SyntaxError should be raised at compile time: UndefinedVariable", false, true),
            ("failure", "", "RETURN 1 AS count", "the result should be, in any order:\n      | count |\n      | 2 |", true, false),
        ] {
            let feature = gherkin::Feature::parse(format!("Feature: Worker\n  Scenario: {id}\n    {setup}When executing query:\n      \"\"\"\n      {query}\n      \"\"\"\n    Then {assertion}\n"), gherkin::GherkinEnv::default()).unwrap();
            let request = serde_json::json!({"id":id,"steps":feature.scenarios[0].steps});
            let bytes = serde_json::to_vec(&request).unwrap();
            input.write_u32(bytes.len().try_into().unwrap()).await.unwrap();
            input.write_all(&bytes).await.unwrap();
            input.flush().await.unwrap();
            let mut observed_progress = false;
            loop {
                let length = output.read_u32().await.unwrap() as usize;
                assert!(length <= 8 * 1024 * 1024);
                let mut bytes = vec![0; length];
                output.read_exact(&mut bytes).await.unwrap();
                let reply: serde_json::Value = serde_json::from_slice(&bytes).unwrap();
                let Some(progress) = reply.get("Planned") else {
                    let finished = &reply["Finished"];
                    assert_eq!(finished["id"],id);
                    assert_eq!(finished["planned"],planned);
                    assert!(!observed_progress || planned);
                    assert_eq!(finished["result"].get("Ok").is_some(),passes,"{reply}");
                    if !passes {
                        assert_eq!(finished["result"]["Err"]["status"],"failed");
                    }
                    break;
                };
                assert_eq!(progress["id"],id);
                assert!(!observed_progress);
                observed_progress = true;
            }
        }
        drop(input);
        assert!(child.wait().await.unwrap().success());
    }).await.expect("production worker must complete and close its databases");
}

#[tokio::test]
async fn cli_runs_bounded_workers_and_short_lifetime_limits_stay_visible() {
    let directory = tempfile::tempdir().unwrap();
    for timeout in [60_000, 1] {
        let path = directory.path().join(format!("report-{timeout}.json"));
        let output = tokio::time::timeout(
            Duration::from_secs(45),
            command()
                .args([
                    "--filter",
                    "Literals1.feature",
                    "--parallelism",
                    "2",
                    "--scenario-timeout-ms",
                    &timeout.to_string(),
                    "--output",
                ])
                .arg(&path)
                .output(),
        )
        .await
        .unwrap()
        .unwrap();
        assert!(
            output.status.success(),
            "{}",
            String::from_utf8_lossy(&output.stderr)
        );
        let report: serde_json::Value =
            serde_json::from_slice(&std::fs::read(path).unwrap()).unwrap();
        assert!(report["scenarios"].as_u64().unwrap() > 0);
        assert!(report["counts"].get("harness_error").is_none(), "{report}");
        let category = if timeout == 1 { "timed_out" } else { "passed" };
        assert!(report["counts"][category].as_u64().unwrap() > 0, "{report}");
    }
}

#[tokio::test]
async fn worker_rejects_oversized_protocol_input_before_a_database_opens() {
    let mut child = command()
        .arg("--worker")
        .stdin(Stdio::piped())
        .stderr(Stdio::null())
        .spawn()
        .unwrap();
    child
        .stdin
        .take()
        .unwrap()
        .write_all(&u32::MAX.to_be_bytes())
        .await
        .unwrap();
    let status = tokio::time::timeout(Duration::from_secs(10), child.wait())
        .await
        .unwrap()
        .unwrap();
    assert!(!status.success());
}

//! Construction budgets exclude parsing and measure allocation requests, not RSS.
use crate::allocations;
use helix_planner::relational as r;

#[test]
fn growing_and_shadowed_scopes_stay_within_compilation_allocation_budgets() {
    for growing in [false, true] {
        for width in [64, 256, 1024, 4095] {
            let source = if growing {
                (0..width)
                    .map(|slot| format!("UNWIND [1] AS v{slot} "))
                    .collect::<String>()
                    + "RETURN v0"
            } else {
                "WITH 1 AS v0 ".to_owned()
                    + &(1..width)
                        .map(|slot| format!("WITH v{} AS v{slot} ", slot - 1))
                        .collect::<String>()
                    + &format!("RETURN v{}", width - 1)
            };
            let syntax = helix_cypher::parse(&source).unwrap();
            let (query, count) = allocations::observe(|| helix_cypher::resolve(&syntax));
            let query = query.unwrap();
            // These ceilings allow ordinary container growth but reject a map
            // per expanding scope. Sparse alias IDs must remain economical too.
            let bytes_per_binding = if growing { 2048 } else { 4096 };
            assert!(
                count.bytes <= bytes_per_binding * (width + 1),
                "growing={growing}, width={width}, count={count:?}"
            );
            assert!(
                count.allocations <= 32 * (width + 1),
                "growing={growing}, width={width}, count={count:?}"
            );
            assert_eq!(query.layout().width(), if growing { width + 1 } else { 2 });
            assert_eq!(query.contracts().len(), width + 1);
            let last = query.contracts().last().unwrap();
            assert_eq!(last.input().len(), if growing { width } else { 1 });
            assert_eq!(last.output().len(), 1);
            assert!(last.output().get(query.returns()[0].1).is_some());
            assert!(last.output().get(r::Slot(u32::MAX)).is_none());
            assert_eq!(last.output().iter().count(), 1);
        }
    }
}

//! End-to-end membership set retention through `HelixDB::query`.
//!
//! Every request runs against a database with the `Attribute` kind index and
//! one without it, and both must answer alike. The resolve counter of the
//! indexed database shows how often a request read a set: once per request
//! unless a `ForEach` frame rebinds a parameter the set reads or a write
//! reaches its footprint.

use std::collections::BTreeMap;

use helix_ast::batch;
use helix_ast::expr::Predicate;
use helix_ast::graph::NodeRef;
use helix_ast::query::{QueryRequest, QueryValue};
use helix_ast::traversal::{self, g};
use helix_ast::value::PropertyInput;

use super::index_membership_tests::{attribute, edge, narrow, node, resolved, seeded};
use crate::encoding::keys::scope::DataScope;
use crate::HelixDB;

struct Pair {
    indexed: HelixDB,
    unindexed: HelixDB,
}

impl Pair {
    async fn seeded(name: &str) -> Self {
        Self {
            indexed: seeded(&format!("{name}-indexed"), DataScope::LegacyUnscoped, true).await,
            unindexed: seeded(
                &format!("{name}-unindexed"),
                DataScope::LegacyUnscoped,
                false,
            )
            .await,
        }
    }

    /// Run `request` on both databases, assert equal outcomes, and return the
    /// response with the sets the indexed database resolved.
    async fn query(&self, request: QueryRequest) -> (crate::Result<serde_json::Value>, usize) {
        let before = resolved(&self.indexed);
        let indexed = self.indexed.query(request.clone()).await;
        let resolves = resolved(&self.indexed) - before;
        let unindexed = self.unindexed.query(request).await;
        match (&indexed, &unindexed) {
            (Ok(indexed), Ok(unindexed)) => assert_eq!(indexed, unindexed),
            (Err(indexed), Err(unindexed)) => {
                assert_eq!(indexed.to_string(), unindexed.to_string());
            }
            (indexed, unindexed) => panic!("{indexed:?} != {unindexed:?}"),
        }
        (indexed, resolves)
    }

    async fn close(self) {
        self.indexed.close().await.unwrap();
        self.unindexed.close().await.unwrap();
    }
}

fn frames<const N: usize>(rows: Vec<[(&str, &str); N]>) -> QueryValue {
    QueryValue::Array(
        rows.into_iter()
            .map(|fields| {
                QueryValue::Object(
                    fields
                        .into_iter()
                        .map(|(name, value)| {
                            (name.to_owned(), QueryValue::String(value.to_owned()))
                        })
                        .collect::<BTreeMap<_, _>>(),
                )
            })
            .collect(),
    )
}

/// Every `Attribute` with the properties the batches write.
fn attributes() -> traversal::Traversal<traversal::Terminal> {
    g().n_with_label("Attribute")
        .values(vec!["uid", "kind", "tagged", "seen"])
}

fn run_high_stack<F: std::future::Future<Output = ()> + 'static>(contract: fn() -> F) {
    std::thread::Builder::new()
        .stack_size(16 * 1024 * 1024)
        .spawn(move || {
            tokio::runtime::Builder::new_current_thread()
                .enable_all()
                .build()
                .unwrap()
                .block_on(contract());
        })
        .unwrap()
        .join()
        .unwrap();
}

/// An ingest batch whose frames create an item, link it, and tag the `B`
/// attributes behind it reads the kind set once for every frame.
#[test]
fn foreach_ingest_batches_resolve_a_set_once() {
    run_high_stack(foreach_ingest_contract);
}

async fn foreach_ingest_contract() {
    let pair = Pair::seeded("retention-e2e-ingest").await;
    let body = batch::write_batch()
        .var_as(
            "item",
            g().add_n("Item", vec![("uid", PropertyInput::param("uid"))]),
        )
        .var_as(
            "a1",
            g().n_with_label_where("Attribute", Predicate::eq("uid", "a1")),
        )
        .var_as(
            "a2",
            g().n_with_label_where("Attribute", Predicate::eq("uid", "a2")),
        )
        .var_as("l1", edge("item", "HAS_ATTRIBUTE", "a1"))
        .var_as("l2", edge("item", "HAS_ATTRIBUTE", "a2"))
        .var_as(
            "tag",
            g().n(NodeRef::var("item"))
                .out(Some("HAS_ATTRIBUTE"))
                .where_(attribute(Predicate::eq("kind", "B")))
                .set_property("tagged", PropertyInput::param("uid")),
        );
    let request = QueryRequest::write(
        batch::write_batch()
            .for_each_param("rows", body)
            .var_as("attributes", attributes())
            .returning(["attributes"]),
    )
    .with_parameter_value(
        "rows",
        frames(vec![
            [("uid", "x1")],
            [("uid", "x2")],
            [("uid", "x3")],
            [("uid", "x4")],
        ]),
    );
    let (response, resolves) = pair.query(request).await;
    let response = response.unwrap();
    assert_eq!(resolves, 1);
    assert!(
        response["attributes"]
            .as_array()
            .unwrap()
            .iter()
            .any(|row| row["uid"] == "a1" && row["tagged"] == "x4"),
        "{response}"
    );
    pair.close().await;
}

/// A body whose set reads a frame parameter resolves it once per frame, and
/// a failing batch leaves no state behind.
#[test]
fn foreach_set_parameters_resolve_per_frame_and_failures_abort() {
    run_high_stack(foreach_set_parameter_contract);
}

async fn foreach_set_parameter_contract() {
    let pair = Pair::seeded("retention-e2e-set-param").await;
    let body = batch::write_batch().var_as(
        "seen",
        g().n_with_label_where("Item", Predicate::eq("uid", "i1"))
            .out(Some("HAS_ATTRIBUTE"))
            .where_(attribute(Predicate::eq_param("kind", "kind")))
            .set_property("seen", PropertyInput::param("tag")),
    );
    let batch = batch::write_batch()
        .for_each_param("rows", body)
        .var_as("attributes", attributes())
        .returning(["attributes"]);
    let (response, resolves) = pair
        .query(QueryRequest::write(batch.clone()).with_parameter_value(
            "rows",
            frames(vec![
                [("kind", "B"), ("tag", "t1")],
                [("kind", "A"), ("tag", "t2")],
                [("kind", "B"), ("tag", "t3")],
            ]),
        ))
        .await;
    response.unwrap();
    assert_eq!(resolves, 3);

    // The second frame binds no tag, so the batch fails and aborts.
    let (failed, _) = pair
        .query(QueryRequest::write(batch.clone()).with_parameter_value(
            "rows",
            QueryValue::Array(vec![
                QueryValue::Object(BTreeMap::from([
                    ("kind".to_owned(), QueryValue::String("A".to_owned())),
                    ("tag".to_owned(), QueryValue::String("t4".to_owned())),
                ])),
                QueryValue::Object(BTreeMap::from([(
                    "kind".to_owned(),
                    QueryValue::String("B".to_owned()),
                )])),
            ]),
        ))
        .await;
    assert!(failed.is_err());
    let (after, _) = pair
        .query(QueryRequest::read(
            batch::read_batch()
                .var_as("attributes", attributes())
                .returning(["attributes"]),
        ))
        .await;
    let after = after.unwrap();
    assert!(
        after["attributes"]
            .as_array()
            .unwrap()
            .iter()
            .all(|row| row["seen"] != "t4"),
        "{after}"
    );
    pair.close().await;
}

/// A statement after a write reads the set again only when the write reached
/// its footprint.
#[test]
fn statements_after_writes_resolve_again_only_when_reached() {
    run_high_stack(statements_after_writes_contract);
}

async fn statements_after_writes_contract() {
    let pair = Pair::seeded("retention-e2e-statements").await;
    let kind_b = || narrow(attribute(Predicate::eq("kind", "B")));
    let attribute_uid =
        |uid: &str| g().n_with_label_where("Attribute", Predicate::eq("uid", uid.to_owned()));
    let writes: Vec<(
        &str,
        traversal::Traversal<traversal::OnNodes, traversal::WriteEnabled>,
        usize,
    )> = vec![
        ("add a note", node("Note", "n9", Some("B")), 1),
        (
            "set an unread property",
            attribute_uid("a2").set_property("title", "t"),
            1,
        ),
        (
            "set the read property",
            attribute_uid("a2").set_property("kind", "B"),
            2,
        ),
        (
            "remove the read property",
            attribute_uid("a2").remove_property("kind"),
            2,
        ),
        ("add an attribute", node("Attribute", "a9", Some("B")), 2),
        ("drop an attribute", attribute_uid("a3").drop(), 2),
    ];
    for (description, write, expected) in writes {
        let (response, resolves) = pair
            .query(QueryRequest::write(
                batch::write_batch()
                    .var_as("before", kind_b())
                    .var_as("write", write)
                    .var_as("after", kind_b())
                    .returning(["before", "after"]),
            ))
            .await;
        response.unwrap();
        assert_eq!(resolves, expected, "{description}");
    }

    // An edge-only write reaches no node index.
    let (response, resolves) = pair
        .query(QueryRequest::write(
            batch::write_batch()
                .var_as("before", kind_b())
                .var_as(
                    "write",
                    g().n_with_label_where("Item", Predicate::eq("uid", "i2"))
                        .out_e(Some("HAS_ATTRIBUTE"))
                        .drop(),
                )
                .var_as("after", kind_b())
                .returning(["before", "after"]),
        ))
        .await;
    let response = response.unwrap();
    assert_eq!(resolves, 1);
    assert_ne!(response["before"], response["after"]);
    pair.close().await;
}

/// Statement pairs that update an unread property and then probe one set with
/// their own residual parameter read the set once per request: entries are
/// keyed by set, so a residual that differs per statement still shares it.
#[test]
fn statements_probing_one_set_with_different_residuals_resolve_it_once() {
    run_high_stack(statements_probing_one_set_contract);
}

async fn statements_probing_one_set_contract() {
    let pair = Pair::seeded("retention-e2e-probes").await;
    let tags = ["t1", "t2", "t3"];
    let batch = (0..tags.len()).fold(batch::write_batch(), |batch, unit| {
        batch
            .var_as(
                &format!("touch{unit}"),
                g().n_with_label_where("Attribute", Predicate::eq("uid", "a1"))
                    .set_property("tagged", PropertyInput::param(format!("t{unit}"))),
            )
            .var_as(
                &format!("probe{unit}"),
                narrow(attribute(Predicate::and(vec![
                    Predicate::eq("kind", "B"),
                    Predicate::eq_param("tagged", format!("t{unit}")),
                ]))),
            )
    });
    let probes = (0..tags.len())
        .map(|unit| format!("probe{unit}"))
        .collect::<Vec<_>>();
    let request = tags.iter().enumerate().fold(
        QueryRequest::write(batch.returning(probes.clone())),
        |request, (unit, tag)| {
            request.with_parameter_value(format!("t{unit}"), QueryValue::String((*tag).to_owned()))
        },
    );
    let (response, resolves) = pair.query(request).await;
    let response = response.unwrap();
    assert_eq!(resolves, 1);
    for probe in probes {
        assert!(
            !response[&probe].as_array().unwrap().is_empty(),
            "{probe}: {response}"
        );
    }
    pair.close().await;
}

//! End-to-end index-served source filters and counts through `HelixDB::query`.
//!
//! Every query runs against a database with the `Item` indexes and one
//! without, which scans and filters per row; both must return the same rows.
//! The indexed plans never scan.

use helix_ast::{batch, expr, index, query, traversal, value};
use helix_planner::{context, exec, planning};

use crate::encoding::keys::scope::DataScope;
use crate::{HelixDB, HelixDbSource};

const ITEMS: i64 = 30;

async fn open(name: &str) -> HelixDB {
    HelixDB::open(HelixDbSource::InMemory {
        database: name.into(),
    })
    .await
    .unwrap()
}

async fn create_index(db: &HelixDB, spec: index::IndexSpec) {
    let receipt = db
        .query(query::QueryRequest::write(
            batch::write_batch()
                .var_as("index", traversal::g().create_index_if_not_exists(spec))
                .returning(["index"]),
        ))
        .await
        .unwrap();
    let operation = receipt["index"]["operation_id"]
        .as_str()
        .unwrap()
        .to_owned();
    tokio::time::timeout(std::time::Duration::from_secs(30), async {
        loop {
            let status = db
                .query(query::QueryRequest::read(
                    batch::read_batch()
                        .var_as("status", traversal::g().get_index_operation(&operation))
                        .returning(["status"]),
                ))
                .await
                .unwrap();
            match status["status"]["status"].as_str().unwrap() {
                "succeeded" => break,
                "queued" | "running" => tokio::task::yield_now().await,
                other => panic!("index failed: {other}"),
            }
        }
    })
    .await
    .unwrap();
}

/// `Item` `i{n}` has `kind` `A`, `B` or `C` (none for every seventh), an
/// unindexed `rank` `n`, and a `uid`; `Note` nodes share the kinds.
fn seed() -> batch::WriteBatch {
    (0..ITEMS).fold(batch::write_batch(), |write, n| {
        let mut properties = vec![
            ("uid", value::PropertyInput::from(format!("i{n}"))),
            ("rank", value::PropertyInput::from(n)),
        ];
        if n % 7 != 0 {
            properties.push((
                "kind",
                value::PropertyInput::from(["A", "B", "C"][(n % 3) as usize]),
            ));
        }
        write
            .var_as(&format!("i{n}"), traversal::g().add_n("Item", properties))
            .var_as(
                &format!("n{n}"),
                traversal::g().add_n(
                    "Note",
                    vec![(
                        "kind",
                        value::PropertyInput::from(["A", "B", "C"][(n % 3) as usize]),
                    )],
                ),
            )
    })
}

async fn seeded(name: &str, indexed: bool) -> HelixDB {
    let db = open(name).await;
    if indexed {
        create_index(&db, index::IndexSpec::node_equality("Item", "kind")).await;
        create_index(&db, index::IndexSpec::node_equality("Item", "uid")).await;
    }
    db.query(query::QueryRequest::write(seed())).await.unwrap();
    db
}

fn read(result: traversal::Traversal<traversal::Terminal>) -> batch::ReadBatch {
    batch::read_batch()
        .var_as("result", result)
        .returning(["result"])
}

/// The response with every row array sorted, so row order does not matter.
fn sorted(mut response: serde_json::Value) -> serde_json::Value {
    if let Some(rows) = response["result"].as_array_mut() {
        rows.sort_by_key(|row| row.to_string());
    }
    response
}

#[test]
fn index_served_sources_and_counts_match_the_per_row_filter() {
    // Counts over branch-residual unions nest cursor polls whose frames
    // exceed the default test stack in debug builds, so run on a dedicated
    // stack.
    std::thread::Builder::new()
        .name("index-served-sources-e2e".to_owned())
        .stack_size(16 * 1024 * 1024)
        .spawn(|| {
            tokio::runtime::Builder::new_current_thread()
                .enable_all()
                .build()
                .expect("index-served sources test runtime builds")
                .block_on(index_served_sources_and_counts_match_the_per_row_filter_contract());
        })
        .expect("index-served sources test thread starts")
        .join()
        .expect("index-served sources test thread completes");
}

async fn index_served_sources_and_counts_match_the_per_row_filter_contract() {
    let indexed = seeded("index-served-sources-indexed", true).await;
    let unindexed = seeded("index-served-sources-unindexed", false).await;
    let items = |predicate: expr::Predicate| traversal::g().n_with_label_where("Item", predicate);
    let wide_uids = (0..120)
        .map(|n| value::PropertyValue::from(format!("i{n}")))
        .chain(core::iter::once(value::PropertyValue::Null))
        .collect::<Vec<_>>();
    let reads = [
        // A partly indexed OR: each branch reads its index and evaluates its
        // own unindexed conjunct; rows several branches accept count once.
        items(expr::Predicate::or(vec![
            expr::Predicate::and(vec![
                expr::Predicate::eq("kind", "B"),
                expr::Predicate::gte("rank", 10),
            ]),
            expr::Predicate::and(vec![
                expr::Predicate::eq("kind", "B"),
                expr::Predicate::lt("rank", 20),
            ]),
            expr::Predicate::eq("uid", "i7"),
        ]))
        .values(vec!["uid"]),
        items(expr::Predicate::or(vec![
            expr::Predicate::and(vec![
                expr::Predicate::eq("kind", "A"),
                expr::Predicate::lt("rank", 20),
            ]),
            expr::Predicate::eq("kind", "C"),
        ]))
        .count(),
        // Counts over a saved stream.
        items(expr::Predicate::eq("kind", "B")).as_("saved").count(),
        traversal::g()
            .n_with_label("Item")
            .where_(expr::Predicate::eq("kind", "C"))
            .store("saved")
            .count(),
        // Lists wider than one index union, with null.
        items(expr::Predicate::is_in(
            "uid",
            value::PropertyValue::Array(wide_uids),
        ))
        .values(vec!["uid"]),
        items(expr::Predicate::or(
            (0..100)
                .map(|n| expr::Predicate::eq("uid", format!("i{n}")))
                .collect(),
        ))
        .count(),
        // Null equality reads only the label's rows outside the lane.
        items(expr::Predicate::eq("kind", value::PropertyValue::Null)).values(vec!["uid"]),
        items(expr::Predicate::and(vec![
            expr::Predicate::eq("kind", value::PropertyValue::Null),
            expr::Predicate::is_in(
                "uid",
                value::PropertyValue::StringArray(vec!["i0".into(), "i1".into(), "i14".into()]),
            ),
        ]))
        .count(),
    ];
    for read in reads.map(read) {
        let prepared = indexed
            .planner_context_scoped_prepared(
                context::ParamBindings::default(),
                DataScope::LegacyUnscoped,
            )
            .await
            .unwrap();
        let plan = planning::plan_read_batch(&read, prepared.context()).unwrap();
        let scans = plan
            .steps()
            .iter()
            .filter(|step| {
                matches!(
                    &step.op,
                    exec::ExecOp::Access { plan } if matches!(
                        plan.as_ref(),
                        exec::ExecAccessPlan::Node(
                            exec::ExecNodeAccessPlan::LabelScan { .. }
                                | exec::ExecNodeAccessPlan::AllScan
                        )
                    )
                )
            })
            .count();
        assert_eq!(scans, 0, "{:?}", plan.steps());
        let expected = unindexed
            .query(query::QueryRequest::read(read.clone()))
            .await
            .unwrap();
        let actual = indexed
            .query(query::QueryRequest::read(read.clone()))
            .await
            .unwrap();
        assert_eq!(sorted(actual), sorted(expected));
    }
    indexed.close().await.unwrap();
    unindexed.close().await.unwrap();
}

